@import "./foundations.css";
@import "./themes.css";
@import "./components.css";


* { box-sizing: border-box; margin: 0; padding: 0; }
html,
body,
#root { width: 100%; min-width: 0; height: 100%; min-height: 0; overflow: hidden; }
body { overflow: hidden; background: var(--bg); color: var(--fg); font-family: var(--font-sans); }
button,
input,
textarea,
select { color: inherit; font: inherit; }
button { cursor: pointer; }
button:disabled { color: var(--text-disabled); cursor: not-allowed; }
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible,
[role="separator"]:focus-visible,
[role="treeitem"]:focus-visible {
  outline: 2px solid var(--accent-cyan); outline-offset: 2px;
}
.workspace-header { display: grid; min-width: 0; grid-template-columns: minmax(220px, 1fr) auto; align-items: center; gap: 1.5rem; border-bottom: 1px solid var(--gutter); padding: 0 1rem; }
.eyebrow { color: var(--muted); font: 600 var(--text-xs) var(--font-mono); letter-spacing: 0.13em; text-transform: uppercase; }
.screen-tabs { display: flex; min-width: 0; max-width: 100%; align-self: stretch; }
.screen-tabs button, .screen-tabs a { border: 0; border-left: 1px solid var(--border); padding: 0 0.9rem; background: transparent; color: var(--muted); font: 600 var(--text-xs) var(--font-mono); letter-spacing: 0.12em; }
.screen-tabs a { display: flex; align-items: center; text-decoration: none; }
.screen-tabs button:last-child { border-right: 1px solid var(--border); }
.screen-tabs button.is-active { border-bottom: 2px solid var(--accent-cyan); color: var(--accent-cyan); }

@media (max-width: 840px) {
  .workspace-header { gap: 0.5rem; }
}

.button { border: 1px solid var(--gutter); border-radius: var(--radius-md); padding: 0.55rem 0.75rem; background: transparent; font: var(--text-sm) var(--font-mono); }
.button:hover:not(:disabled) { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.button.is-active { border-color: var(--accent-yellow); color: var(--accent-yellow); }
.file-explorer { --file-tree-row-height: 22px; display: grid; min-width: 0; min-height: 0; grid-template-rows: 42px minmax(0, 1fr); overflow: hidden; }
.source-code-viewer { --source-gutter-width: 6.25rem; --source-copy-padding: 0.85rem; width: 100%; height: 100%; min-width: 0; min-height: 0; overflow: auto; background: var(--source-bg); color: var(--source-fg); font: var(--text-md)/1.55 var(--font-mono); outline: 0; tab-size: 4; }
.source-code-viewer.is-revealed { box-shadow: inset 2px 0 var(--accent-cyan); }
.source-code-viewer { position: relative; }
.source-code-viewer:focus-visible { box-shadow: inset 2px 0 var(--accent-cyan), inset 0 0 0 1px color-mix(in srgb, var(--accent-primary) 42.000%, transparent); }
.source-code-content { width: max-content; min-width: 100%; padding: 0.65rem 0; }
.source-code-chunk { display: flow-root; }
.source-code-line,
.source-fold-placeholder { display: grid; width: 100%; min-width: max-content; grid-template-columns: var(--source-gutter-width) minmax(max-content, 1fr); align-items: baseline; border: 0; background: transparent; font: inherit; line-height: inherit; text-align: left; white-space: pre; }
.source-code-line:hover { background: color-mix(in srgb, var(--text-primary) 3.000%, transparent); }
.source-code-line.is-selected { background: color-mix(in srgb, var(--accent-primary) 11.000%, transparent); box-shadow: inset 2px 0 var(--accent-cyan); }
.source-line-gutter { position: sticky; z-index: 1; left: 0; display: grid; min-height: 1.55em; grid-template-columns: 2rem 1fr; align-items: baseline; padding: 0 0.7rem 0 0.35rem; background: var(--surface-code-gutter); color: var(--text-muted); text-align: right; user-select: none; }
.source-line-number { display: flex; min-height: 1.55em; grid-column: 2; align-items: center; justify-content: flex-end; }
.source-line-text,
.source-fold-copy { display: block; min-width: max-content; padding: 0 var(--source-copy-padding); font: inherit; }
.source-token { white-space: pre; }
.source-code-viewer[data-wrap="true"] .source-code-content { width: 100%; min-width: 0; }
.source-code-viewer[data-wrap="true"] .source-code-line { min-width: 0; grid-template-columns: var(--source-gutter-width) minmax(0, 1fr); white-space: normal; }
.source-code-viewer[data-wrap="true"] .source-line-text { min-width: 0; white-space: pre-wrap; overflow-wrap: anywhere; }
.source-code-viewer[data-wrap="true"] .source-token { white-space: inherit; }
.source-fold-placeholder { align-items: start; padding: 0.2rem 0; color: var(--accent-info); }
.source-fold-placeholder:hover { background: color-mix(in srgb, var(--accent-success) 4.000%, transparent); }
.source-fold-placeholder:focus-within { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent-success) 45.000%, transparent); }
.source-fold-placeholder > .source-line-gutter { z-index: 2; height: 1.55em; align-self: start; color: var(--accent-success); }
.source-fold-marker,
.source-fold-toggle { grid-column: 2; justify-content: flex-end; color: var(--accent-success); text-align: right; }
.source-fold-marker,
.source-fold-toggle { display: flex; min-height: 1.55em; align-items: center; border: 0; padding: 0; background: transparent; font: inherit; line-height: inherit; }
.source-fold-marker:hover,
.source-fold-marker:focus-visible,
.source-fold-toggle:hover,
.source-fold-toggle:focus-visible { outline: 0; color: var(--accent-warning); }
.source-fold-spacer { grid-column: 1; }
.source-call-graph-line,
.source-call-graph-node { display: grid; width: calc(100% + var(--source-gutter-width) + var(--source-copy-padding)); min-height: 1.55em; margin-left: calc(0rem - var(--source-gutter-width) - var(--source-copy-padding)); grid-template-columns: var(--source-gutter-width) max-content; align-items: baseline; color: inherit; font: inherit; line-height: inherit; white-space: pre; }
.source-call-graph-line > span:first-child,
.source-call-graph-node-marker { position: sticky; z-index: 1; left: 0; box-sizing: border-box; align-self: stretch; padding-left: 0.35rem; background: var(--surface-code-gutter); }
.source-call-graph-line > span:first-child { pointer-events: none; }
.source-call-graph-line > span:last-child,
.source-call-graph-node > span:last-child { padding-left: var(--source-copy-padding); }
.source-call-graph-node-wrap { min-width: max-content; }
.source-call-graph-node { border: 0; padding: 0; background: transparent; text-align: left; }
.source-call-graph-node { align-items: center; }
.source-call-graph-node:hover,
.source-call-graph-node:focus-visible { outline: 0; background: color-mix(in srgb, var(--accent-warning) 8.000%, transparent); color: var(--accent-warning); }
.source-call-graph-node:focus-visible { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent-warning) 55.000%, transparent); }
.source-call-graph-node-marker { display: flex; min-height: 1.55em; align-self: center; align-items: center; justify-content: flex-end; margin-left: 0; padding: 0 0.7rem 0 0.35rem; color: var(--accent-success); text-align: right; }
.source-call-graph-node-source { width: calc(100% + var(--source-gutter-width) + var(--source-copy-padding)); margin: 0.1rem 0 0.35rem calc(0rem - var(--source-gutter-width) - var(--source-copy-padding)); padding: 0.2rem 0; background: color-mix(in srgb, var(--shadow-color) 18.000%, transparent); color: var(--source-fg); }
.source-call-graph-node-source-line { display: grid; min-height: 1.55em; grid-template-columns: var(--source-gutter-width) max-content; align-items: baseline; }
.source-call-graph-node-source-line > span { position: sticky; z-index: 1; left: 0; box-sizing: border-box; padding: 0 0.7rem 0 0.35rem; background: var(--surface-code-gutter); color: var(--text-muted); text-align: right; user-select: none; }
.source-call-graph-node-source-line > code { border-left: 1px solid var(--accent-success); padding: 0 var(--source-copy-padding); font: inherit; }
.diagram-canvas { position: relative; }
.diagram-canvas.is-enabled { overflow: hidden; padding: 0; outline: 0; cursor: grab; overscroll-behavior: contain; touch-action: none; }
.diagram-canvas.is-enabled:focus-visible { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent-primary) 55.000%, transparent); }
.diagram-canvas.is-enabled.is-dragging { cursor: grabbing; }
.diagram-canvas__surface { display: inline-block; min-width: max-content; transform-origin: 0 0; }
/* Allow text to be re-rasterized at each zoom scale; will-change: transform retains a blurry cached raster. */
.diagram-canvas.is-enabled .diagram-canvas__surface { position: absolute; top: 0; left: 0; }
.diagram-canvas.is-enabled.is-dragging .diagram-canvas__surface { user-select: none; }
.diagram-canvas:not(.is-enabled) { display: grid; place-items: center; overflow: auto; padding: 2rem; }
.diagram-canvas__controls { position: absolute; z-index: 8; right: 0.7rem; bottom: 0.7rem; display: flex; align-items: center; overflow: hidden; border: 1px solid var(--gutter); border-radius: var(--radius-sm); background: color-mix(in srgb, var(--surface-panel) 90.000%, transparent); box-shadow: 0 4px 14px color-mix(in srgb, var(--shadow-color) 30.000%, transparent); color: var(--muted); font: var(--text-2xs) var(--font-mono); }
.diagram-canvas__controls output { min-width: 4.2rem; padding: 0.35rem 0.55rem; text-align: center; }
.diagram-canvas__controls button { border: 0; border-left: 1px solid var(--gutter); padding: 0.35rem 0.55rem; background: transparent; color: var(--accent-cyan); font: inherit; cursor: pointer; }
.diagram-canvas__controls button:hover,
.diagram-canvas__controls button:focus-visible { outline: 0; background: color-mix(in srgb, var(--accent-primary) 10.000%, transparent); color: var(--fg); }
.ascii-line { white-space: pre; }
@keyframes tree-status-pulse { 50% { opacity: 0.35; } }
@keyframes spin { to { transform: rotate(360deg); } }

@media (max-width: 760px), (max-width: 900px) and (hover: none) and (pointer: coarse) {
  .workspace-header { grid-template-columns: 1fr auto; gap: 0.75rem; padding: 0.6rem; }
  .screen-tabs { grid-column: 2; grid-row: 1; }
}

.mapping-poc-shell { display: grid; width: 100%; min-width: 0; height: 100dvh; overflow: hidden; grid-template-rows: 58px minmax(0, 1fr); background: var(--bg); }
.mapping-poc-workspace { display: grid; min-width: 0; min-height: 0; grid-template-rows: auto minmax(0, 1fr) 32px; }
.mapping-poc-canvas { min-width: 0; min-height: 0; background-color: var(--surface-canvas); background-image: linear-gradient(var(--grid-canvas) 1px, transparent 1px), linear-gradient(90deg, var(--grid-canvas) 1px, transparent 1px); background-size: 24px 24px; }
.mapping-poc-graph-stage { position: relative; display: inline-block; min-width: max-content; margin: 64px 0 0 190px; cursor: crosshair; }
.mapping-grid-tools { position: absolute; left: 0; bottom: calc(100% + 38px); display: flex; align-items: center; gap: var(--space-4); width: 850px; color: var(--muted); font: var(--text-sm) var(--font-mono); }
.mapping-grid-tools button,
.mapping-grid-box-tools button { border: 1px solid var(--border); border-radius: var(--radius-sm); background: var(--surface-raised); color: var(--fg); padding: 3px 7px; cursor: pointer; font: var(--text-xs) var(--font-mono); }
.mapping-grid-tools button:disabled,
.mapping-grid-box-tools button:disabled { opacity: 0.4; cursor: default; }
.mapping-grid-box { position: absolute; border: 1px dotted color-mix(in srgb, var(--accent-primary) 18.000%, transparent); pointer-events: none; }
.mapping-grid-box.is-container { border-color: var(--accent-purple); }
.mapping-grid-box-tools { position: absolute; bottom: calc(100% + 4px); left: 0; display: flex; gap: 3px; pointer-events: auto; z-index: 5; }
.mapping-grid-box.is-container > .mapping-grid-box-tools { top: calc(100% + 4px); bottom: auto; }
.mapping-grid-placement { position: absolute; border: 1px solid var(--accent-yellow); background: color-mix(in srgb, var(--accent-warning) 12.000%, transparent); pointer-events: none; z-index: 8; }
.mapping-grid-local { pointer-events: none; }
.mapping-grid-local [data-mapping-static-ui],
.mapping-grid-local .mapping-poc-selection-menu { pointer-events: auto; }
.mapping-poc-ascii { min-width: max-content; color: var(--fg); font: var(--text-lg)/1.4 var(--font-mono); white-space: pre; }
.mapping-poc-cell-probe { position: absolute; visibility: hidden; font: var(--text-lg)/1.4 var(--font-mono); pointer-events: none; white-space: pre; }
.mapping-poc-node-layer { position: absolute; z-index: 1; inset: 0; pointer-events: none; }
.mapping-poc-node-hit { position: absolute; border-bottom: 1px dotted color-mix(in srgb, var(--accent-secondary) 38.000%, transparent); background: color-mix(in srgb, var(--accent-secondary) 2.000%, transparent); }
.mapping-poc-node-hit.is-mapped { border-color: color-mix(in srgb, var(--accent-primary) 60.000%, transparent); background: color-mix(in srgb, var(--accent-primary) 3.000%, transparent); }
.mapping-poc-node-hit.is-selected { border-color: var(--accent-yellow); background: color-mix(in srgb, var(--accent-warning) 20.000%, transparent); box-shadow: inset 2px 0 var(--accent-yellow); }
.mapping-poc-node-hit.is-selected.is-prompt-target { border-color: var(--accent-purple); background: color-mix(in srgb, var(--accent-secondary) 25.000%, transparent); box-shadow: inset 2px 0 var(--accent-purple), 0 0 12px color-mix(in srgb, var(--accent-secondary) 18.000%, transparent); }
.mapping-poc-a-section-layer { position: absolute; z-index: 4; inset: 0; pointer-events: none; }
.mapping-poc-a-section { position: absolute; right: 0; left: 0; border-top: 1px dashed color-mix(in srgb, var(--accent-secondary) 22.000%, transparent); pointer-events: none; }
.mapping-poc-a-section:last-child { border-bottom: 1px dashed color-mix(in srgb, var(--accent-secondary) 22.000%, transparent); }
.mapping-poc-a-section.is-open { border-color: var(--accent-purple); background: color-mix(in srgb, var(--accent-secondary) 4.000%, transparent); }
.mapping-poc-a-section > button { position: absolute; top: 3px; right: calc(100% + 10px); display: flex; width: 174px; min-height: 24px; align-items: center; gap: 0.45rem; border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 0 0.45rem; background: color-mix(in srgb, var(--surface-app) 92.000%, transparent); color: var(--muted); pointer-events: auto; font: 8px var(--font-mono); text-align: left; white-space: nowrap; }
.mapping-poc-a-section > button span { display: grid; width: 15px; height: 15px; flex: none; place-items: center; border: 1px solid var(--gutter); color: var(--accent-purple); }
.mapping-poc-a-section > button:hover,
.mapping-poc-a-section > button[aria-pressed="true"] { border-color: var(--accent-purple); background: color-mix(in srgb, var(--accent-secondary) 12.000%, transparent); color: var(--fg); }
.mapping-poc-selection-rect { position: absolute; z-index: 2; border: 1px solid var(--accent-cyan); background: color-mix(in srgb, var(--accent-primary) 7.000%, transparent); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-primary) 14.000%, transparent); pointer-events: none; transition: border-color 140ms ease, background 140ms ease, box-shadow 140ms ease; }
.mapping-poc-selection-rect.is-composing { border-color: var(--accent-purple); background: color-mix(in srgb, var(--accent-secondary) 12.000%, transparent); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-secondary) 24.000%, transparent), inset 0 0 28px color-mix(in srgb, var(--accent-secondary) 7.000%, transparent); }
.mapping-poc-selection-rect.is-generating { border-color: var(--accent-yellow); background: color-mix(in srgb, var(--accent-warning) 12.000%, transparent); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-warning) 25.000%, transparent), 0 0 22px color-mix(in srgb, var(--accent-warning) 14.000%, transparent); animation: mapping-poc-prompt-pulse 1.25s ease-in-out infinite; }
.mapping-poc-selection-rect.is-applied { border-color: var(--accent-success); background: color-mix(in srgb, var(--accent-success) 14.000%, transparent); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-success) 24.000%, transparent), inset 0 0 30px color-mix(in srgb, var(--accent-success) 7.000%, transparent); }
.mapping-poc-selection-rect.is-error { border-color: var(--accent-danger); background: color-mix(in srgb, var(--accent-danger) 12.000%, transparent); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-danger) 25.000%, transparent); }
.mapping-poc-selection-rect.is-asking { border-color: var(--accent-green); background: color-mix(in srgb, var(--accent-success) 10.000%, transparent); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-success) 22.000%, transparent), inset 0 0 28px color-mix(in srgb, var(--accent-success) 6.000%, transparent); }
.local-chat-source-highlight { position: absolute; z-index: 3; border: 1px solid var(--accent-green); background: color-mix(in srgb, var(--accent-success) 13.000%, transparent); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-success) 28.000%, transparent), inset 0 0 30px color-mix(in srgb, var(--accent-success) 8.000%, transparent), 0 0 22px color-mix(in srgb, var(--accent-success) 14.000%, transparent); pointer-events: none; }
.local-chat-source-highlight > span { position: absolute; right: -1px; bottom: 100%; border: 1px solid var(--accent-green); border-bottom: 0; padding: 0.2rem 0.35rem; background: color-mix(in srgb, var(--surface-app) 96.000%, transparent); color: var(--accent-green); font: 700 7px var(--font-mono); letter-spacing: 0.1em; white-space: nowrap; }
@keyframes mapping-poc-prompt-pulse { 50% { background: color-mix(in srgb, var(--accent-warning) 19.000%, transparent); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-warning) 35.000%, transparent), 0 0 28px color-mix(in srgb, var(--accent-warning) 22.000%, transparent); } }
/* Keep selection actions above connections, subtree toggles, and anchor targets (layers 6–8). */
.mapping-poc-selection-menu { position: absolute; z-index: 10; display: flex; width: 224px; overflow: hidden; border: 1px solid var(--gutter); border-radius: var(--radius-md); background: var(--surface-app); box-shadow: 0 10px 30px color-mix(in srgb, var(--shadow-color) 45.000%, transparent); flex-direction: column; cursor: default; font: var(--text-2xs) var(--font-mono); }
.mapping-poc-selection-menu.has-floating-ask { overflow: visible; }
.mapping-poc-selection-menu > header { display: flex; min-width: 0; padding: 0.5rem 0.6rem; color: var(--muted); flex-direction: column; gap: 0.22rem; }
.mapping-poc-selection-menu > header em { color: var(--muted); font: 8px var(--font-mono); font-style: normal; }
.mapping-poc-selection-menu > header em.is-covered { color: var(--accent-success); }
.mapping-poc-selection-menu > header em.is-missing { color: var(--accent-danger); }
.mapping-poc-selection-menu > header small { overflow: hidden; color: var(--accent-cyan); font: 8px var(--font-mono); text-overflow: ellipsis; white-space: nowrap; }
.mapping-poc-selection-menu > header small.is-composing { color: var(--accent-purple); }
.mapping-poc-selection-menu > header small.is-asking { color: var(--accent-green); }
.mapping-poc-selection-menu > header small.is-generating { color: var(--accent-yellow); }
.mapping-poc-selection-menu > header small.is-error { color: var(--accent-danger); white-space: normal; }
.mapping-poc-selection-actions { display: flex; flex-direction: column; }
.mapping-projection-choice { display: flex; flex-direction: column; gap: var(--space-2); padding: var(--space-3) 9px; color: var(--accent-cyan); }
.mapping-projection-choice select { max-width: 290px; background: var(--bg); color: var(--fg); font: inherit; }
.mapping-projection-status { max-width: 280px; padding: var(--space-3) 9px; color: var(--accent-yellow); white-space: normal; }
.mapping-poc-selection-menu button { display: flex; min-height: 34px; align-items: center; gap: 0.55rem; border: 0; border-top: 1px solid var(--border); padding: 0 0.6rem; background: transparent; color: var(--accent-cyan); font: var(--text-2xs) var(--font-mono); text-align: left; }
.mapping-poc-selection-menu button:hover:not(:disabled),
.mapping-poc-selection-menu button:focus-visible { background: color-mix(in srgb, var(--accent-primary) 9.000%, transparent); color: var(--fg); }
.mapping-poc-selection-menu kbd { display: grid; width: 19px; height: 19px; place-items: center; border: 1px solid var(--gutter); border-radius: 2px; color: var(--accent-yellow); font: 8px var(--font-mono); }
.mapping-poc-selection-actions button.is-ask { color: var(--accent-green); }
.mapping-poc-selection-actions button.is-ask:hover,
.mapping-poc-selection-actions button.is-ask:focus-visible { background: color-mix(in srgb, var(--accent-success) 9.000%, transparent); }
.mapping-poc-prompt-form { display: flex; border-top: 1px solid var(--border); padding: 0.6rem; flex-direction: column; gap: 0.45rem; }
.mapping-poc-prompt-form label { color: var(--accent-purple); font: 700 8px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; }
.mapping-poc-prompt-form textarea { width: 100%; min-height: 76px; resize: vertical; border: 1px solid var(--gutter); border-radius: var(--radius-sm); padding: 0.5rem; outline: none; background: var(--surface-inset); color: var(--fg); font: var(--text-xs)/1.45 var(--font-mono); }
.mapping-poc-prompt-form textarea:focus { border-color: var(--accent-purple); box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent-secondary) 12.000%, transparent); }
.mapping-poc-prompt-form footer { display: flex; justify-content: flex-end; gap: 0.35rem; }
.mapping-poc-prompt-form footer button { min-height: 27px; border: 1px solid var(--gutter); border-radius: var(--radius-sm); padding: 0 0.55rem; }
.mapping-poc-prompt-form footer button.is-primary { border-color: color-mix(in srgb, var(--accent-secondary) 55.000%, transparent); background: color-mix(in srgb, var(--accent-secondary) 15.000%, transparent); color: var(--accent-purple); }
.local-chat-ask-form { display: flex; border-top: 1px solid var(--border); padding: 0.6rem; background: color-mix(in srgb, var(--surface-app) 98.000%, transparent); flex-direction: column; gap: 0.45rem; }
.local-chat-ask-form.is-floating { position: absolute; top: -1px; left: calc(100% + 9px); width: 276px; border: 1px solid var(--accent-green); border-radius: var(--radius-md); box-shadow: 0 14px 38px color-mix(in srgb, var(--shadow-color) 50.000%, transparent); }
.local-chat-ask-form label { color: var(--accent-green); font: 700 8px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; }
.local-chat-ask-form textarea { width: 100%; min-height: 64px; resize: vertical; border: 1px solid var(--gutter); border-radius: var(--radius-sm); padding: 0.5rem; outline: none; background: var(--surface-inset); color: var(--fg); font: var(--text-xs)/1.45 var(--font-mono); }
.local-chat-ask-form textarea:focus { border-color: var(--accent-green); box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent-success) 12.000%, transparent); }
.local-chat-ask-form p { color: var(--muted); font: 8px/1.4 var(--font-mono); }
.local-chat-ask-form footer { display: flex; justify-content: flex-end; gap: 0.35rem; }
