.mapping-source-body { display: flex; flex: 1; min-height: 0; min-width: 0; overflow: hidden; }
.mapping-source-main { display: flex; flex: 1; flex-direction: column; min-width: 0; min-height: 0; }
.mapping-source-main > .source-code-viewer { flex: 1; height: auto; contain: strict; }
.mapping-source-file-header button,
.repository-file-explorer button { font: inherit; color: inherit; background: transparent; border: 0; cursor: pointer; }
.mapping-source-file-header button:disabled { opacity: .4; cursor: default; }
.mapping-source-toolbar { flex-wrap: wrap; gap: var(--space-3); }
.source-navigation-hint { padding: var(--space-1) var(--space-6); color: var(--accent-cyan); }
.repository-file-explorer { width: 190px; max-width: 40%; flex: none; min-height: 0; overflow: auto; overscroll-behavior: contain; border-right: 1px solid var(--gutter); padding: var(--space-4); }
.repository-file-list { list-style: none; padding: 0; margin: 0; }
.repository-file-list .repository-file-list { padding-left: var(--space-6); }
.repository-file-list button { text-align: left; white-space: nowrap; padding: 3px 5px; }
.repository-file-list button[aria-current="page"] { background: var(--surface-selected); color: var(--accent-cyan); }
.repository-file-explorer button:focus-visible { outline: 1px solid var(--accent-cyan); }

.canvas-transfer-menu { position: fixed; z-index: 10000; width: 304px; max-width: calc(100vw - 16px); max-height: calc(100vh - 16px); overflow: auto; padding: var(--space-3); background: var(--surface-raised); border: 1px solid var(--border); border-radius: var(--radius-lg); color: var(--fg); box-shadow: 0 8px 24px color-mix(in srgb, var(--shadow-color) 53.333%, transparent); font: var(--text-md) var(--font-mono); }
.canvas-transfer-menu button { width: 100%; text-align: left; padding: 9px; border: 0; border-radius: var(--radius-sm); background: transparent; color: inherit; cursor: pointer; font: inherit; }
.canvas-transfer-menu button:hover,
.canvas-transfer-menu button:focus-visible { background: color-mix(in srgb, var(--text-primary) 8.235%, transparent); }
.canvas-transfer-menu button:disabled { opacity: .5; cursor: default; }

[data-diagram-selected="true"] { outline: 2px solid var(--accent-primary); outline-offset: 3px; }
.diagram-selection-marquee { position: fixed; border: 1px solid var(--accent-primary); background: color-mix(in srgb, var(--accent-primary) 15.000%, transparent); pointer-events: none; z-index: 1000; }
.mapping-empty-canvas { position: absolute; top: 48px; left: 0; white-space: nowrap; color: var(--muted); }
.mapping-transfer-busy { position: fixed; inset: 0; z-index: 2000; display: grid; place-items: center; background: color-mix(in srgb, var(--shadow-color) 25.000%, transparent); cursor: progress; }

.mapping-floating-pane.is-transfer-target { border: 2px solid var(--accent-cyan); box-shadow: 0 0 0 5px color-mix(in srgb, var(--accent-primary) 18.000%, transparent), 0 8px 25px color-mix(in srgb, var(--shadow-color) 53.333%, transparent); }
.mapping-transfer-picker { padding: var(--space-5); border: 1px solid var(--accent-cyan); border-radius: var(--radius-md); margin-bottom: 12px; background: color-mix(in srgb, var(--accent-primary) 8.000%, transparent); }
.mapping-transfer-picker p { margin: 0 0 8px; color: var(--fg); font-size: var(--text-sm); }
.mapping-transfer-picker button { padding: var(--space-3) 9px; margin: 4px 6px 0 0; border: 1px solid var(--gutter); border-radius: var(--radius-sm); color: var(--fg); background: var(--bg); cursor: pointer; }
.mapping-transfer-picker button:disabled { opacity: .4; cursor: default; }
.mapping-transfer-picker label { color: var(--fg); font: var(--text-sm) var(--font-mono); }
.mapping-transfer-picker h2 { font: 600 14px var(--font-mono); margin: 0 0 10px; color: var(--accent-cyan); }
.mapping-transfer-picker input { display: block; box-sizing: border-box; width: 100%; margin: 6px 0; padding: var(--space-4); }
.mapping-transfer-picker p.mapping-transfer-error { color: var(--accent-danger); padding: var(--space-4); border: 1px solid var(--accent-danger); }
.mapping-transfer-picker p.mapping-transfer-hint { margin: 10px 0 0; color: var(--muted); }
.mapping-transfer-busy > div { max-width: 480px; padding: 24px; border: 1px solid var(--accent-cyan); border-radius: var(--radius-lg); background: var(--bg); }
.mapping-transfer-busy p { font-size: var(--text-md); }

.code-panel { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.code-panel-summary, .code-panel-file > header { display: flex; align-items: center; gap: var(--space-5); padding: var(--space-4) var(--space-6); flex-wrap: wrap; }
.code-panel-summary { flex: 0 0 auto; border-bottom: 1px solid var(--border-default); }
.code-panel-content { overflow: auto; flex: 1; min-height: 0; overflow-anchor: auto; }
.code-panel-file > header { position: sticky; top: 0; z-index: 2; background: var(--surface-control); }
.code-panel-file > header strong { flex: 1; overflow-wrap: anywhere; }
.code-panel-file > header small { color: var(--text-secondary); }
.code-panel-file .source-code-viewer { max-height: none; height: auto; overflow: visible; flex: none; }
.code-panel-file > p { padding: var(--space-4) var(--space-6); }
.code-panel-origins { display: flex; gap: var(--space-4); padding: 5px var(--space-4); color: var(--accent-info); }
.code-panel-origins > span { border: 1px solid var(--border-default); border-radius: var(--radius-md); padding: var(--space-1) var(--space-3); }
[data-code-panel-highlight=true], [data-panel-node-highlight=true] { background: var(--border-strong) !important; outline: 1px solid var(--accent-info); }
.source-gap { padding: var(--space-2) var(--space-6); border-block: 1px solid var(--surface-hover); background: var(--surface-control); }
.source-gap button { width: 100%; color: var(--text-secondary); font: inherit; background: none; border: 0; cursor: pointer; }

/* Workspace chrome lives in the floating Menu; the canvas owns the full viewport. */
.mapping-poc-shell, .mapping-poc-workspace { grid-template-rows: minmax(0, 1fr); }
.mapping-menu-content { display: flex; flex-direction: column; gap: 12px; padding: 12px; }
.mapping-menu-content .mapping-submenu { flex-wrap: wrap; padding: 0; }
.mapping-menu-content .mapping-submenu > div { width: 100%; }
.mapping-menu-content .mapping-submenu input { width: 100%; }
.mapping-menu-content .mapping-submenu small { display: block; }
.mapping-menu-content .mapping-workspace-actions { flex-wrap: wrap; justify-content: flex-start; }
.mapping-menu-content .mapping-agent-status { width: 100%; justify-content: flex-start; }
.mapping-menu-content .screen-tabs { align-self: flex-start; }
.mapping-menu-status { padding: 0 12px 12px; color: var(--muted); font-size: 10px; overflow-wrap: anywhere; }
